def solve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {}) or {}
    pins = data.get("pins", {}) or {}
    features = data.get("features", []) or []
    names = sorted(packages)
    best_vector = None
    best_versions = None

    constraints = {name: tuple(interval) for name, interval in roots.items()}

    def intersect(old, new):
        if old is None:
            return new
        low, high = old
        if new[0] is not None and (low is None or new[0] > low):
            low = new[0]
        if new[1] is not None and (high is None or new[1] < high):
            high = new[1]
        if low is not None and high is not None and low > high:
            return False
        return (low, high)

    def contains(interval, version):
        if interval is None:
            return True
        low, high = interval
        return (low is None or low <= version) and (high is None or version <= high)

    def is_acyclic(graph):
        visiting = set()
        visited = set()

        def visit(name):
            if name in visiting:
                return False
            if name in visited:
                return True
            visiting.add(name)
            for dep_name in graph.get(name, ()):
                if not visit(dep_name):
                    return False
            visiting.remove(name)
            visited.add(name)
            return True

        return all(visit(name) for name in graph)

    def search(assigned, pending, current_constraints, graph):
        nonlocal best_vector, best_versions

        if not pending:
            if not is_acyclic(graph):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(assigned)
            return

        name = min(pending)
        if name not in packages:
            return

        interval = current_constraints.get(name)
        next_pending = set(pending)
        next_pending.remove(name)

        for row in ordered_rows(packages[name]):
            version = row["version"]
            if not contains(interval, version):
                continue
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue

            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_constraints = dict(current_constraints)
            next_graph = dict(graph)
            active_deps = dependencies(row, features)
            next_graph[name] = tuple(dep_name for dep_name, _ in active_deps)
            valid = True

            for dep_name, dep_interval in active_deps:
                merged = intersect(next_constraints.get(dep_name), dep_interval)
                if merged is False:
                    valid = False
                    break
                next_constraints[dep_name] = merged
                if dep_name in next_assigned and not contains(merged, next_assigned[dep_name]):
                    valid = False
                    break
                if dep_name not in next_assigned:
                    next_pending.add(dep_name)

            if valid:
                search(next_assigned, next_pending, next_constraints, next_graph)

    for low, high in roots.values():
        if low is not None and high is not None and low > high:
            return {"error": "unsatisfiable"}

    search({}, set(roots), constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
